section.content:
// Schema version 10: Add fileSyncStatus table for Zustand store persistence
this.version(10).stores({
    // ... existing tables
    fileSyncStatus: 'id, updatedAt',
}).upgrade(async () => {
    logDexieMigration(10, 'file-sync-status-store', 'started');
    markMigrationApplied(10);
    logDexieMigration(10, 'file-sync-status-store', 'completed', {
        tableName: 'fileSyncStatus',
        itemsCount: 0
    });
});

export async function getFileMetadata(
    projectId: string,
    filePath: string
): Promise<FileMetadataRecord | undefined> {
    return db.fileMetadata
        .where('[projectId+path]')
        .equals([projectId, filePath])
        .first();
}

export async function upsertFileMetadata(
    record: Omit<FileMetadataRecord, 'createdAt' | 'updatedAt'>
): Promise<void> {
    const now = Date.now();
    const existing = await getFileMetadata(record.projectId, record.path);

    await db.fileMetadata.put({
        ...record,
        createdAt: existing?.createdAt || now,
        updatedAt: now,
    });
}

import EventEmitter from 'eventemitter3'

export interface WorkspaceEvents {
  // File System Events
  'file:created': [{ path: string; source: 'local' | 'editor' | 'agent' }]
  'file:modified': [{ path: string; source: 'local' | 'editor' | 'agent' }]
  'file:deleted': [{ path: string; source: 'local' | 'editor' | 'agent' }]

  // Sync Events
  'sync:started': [{ fileCount: number; direction: 'to-wc' | 'to-local' | 'bidirectional' }]
  'sync:progress': [{ current: number; total: number; currentFile: string }]
  'sync:completed': [{ success: boolean; timestamp: Date; filesProcessed: number }]
  'sync:error': [{ error: Error; file?: string }]

  // Agent Activity Events
  'agent:tool:started': [{ toolName: string; toolCallId: string; args: Record<string, unknown> }]
  'agent:tool:completed': [{ toolName: string; toolCallId: string; success: boolean; result?: unknown }]
  'agent:tool:failed': [{ toolName: string; toolCallId: string; error: string }]
}

export type WorkspaceEventEmitter = EventEmitter<WorkspaceEvents>

export function createWorkspaceEventBus(): WorkspaceEventEmitter {
  return new EventEmitter<WorkspaceEvents>()
}

finding.description:
PDF.js requires worker configuration. The worker must be loaded before parsing:
```javascript
pdfjsLib.GlobalWorkerOptions.workerSrc = '../../node_modules/pdfjs-dist/build/pdf.worker.mjs';
const loadingTask = pdfjsLib.getDocument(url);
const pdf = await loadingTask.promise;
```

Dexie.js provides type-safe IndexedDB wrapper with schema versioning:
```javascript
const db = new Dexie('FriendsAndPetsDB');
db.version(1).stores({
    friends: "++id,name,isCloseFriend",
    pets: "++id,name,kind"
});
db.friends.add({name: "Ingemar Bergman", isCloseFriend: 0});
```

note.description:
The PDF.js worker must be loaded before parsing. In Vite, configure the worker path:
```javascript
import * as pdfjsLib from 'pdfjs-dist';
pdfjsLib.GlobalWorkerOptions.workerSrc = new URL(
  'pdfjs-dist/build/pdf.worker.mjs',
  import.meta.url
).toString();
```
